import {Router} from '../framework/router.ts';
import {withErrors} from '../framework/errors.ts';

const audit = { get(_name: string, callback: () => Promise<string>) { return callback; } };
export const auditCallback = audit.get('orders', async () => { throw new Error('audit'); });
export function registerOrders(router: Router) {
  router.get('/orders/:id', withErrors(async (req,res) => {
    const values = await Promise.all([req.id].map(async value => value.toUpperCase()));
    if(req.fail) throw new Error('order read');
    return res.send(values[0]);
  }));
  router.delete('/orders/:id', withErrors(async (req,res) => {
    if(req.fail) throw new Error('order delete');
    return res.send('deleted:'+req.id);
  }));
}

import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {documentation, unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

describe('Router registration and order', () => {
  it('preserves registration order, methods, and paths', () => {
    const router = makeRouter();
    assert.deepEqual(
      router.routes.map(r => ({method: r.method, path: r.path})),
      [
        {method: 'GET', path: '/accounts/:id'},
        {method: 'POST', path: '/accounts'},
        {method: 'GET', path: '/health'},
        {method: 'GET', path: '/orders/:id'},
        {method: 'DELETE', path: '/orders/:id'},
      ]
    );
  });
});

describe('Successful route handling', () => {
  it('handles GET /accounts/:id successfully', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    let nextCalled = false;
    const result = await route.handler(
      {id: '123'},
      {send: val => val},
      () => { nextCalled = true; }
    );
    assert.equal(result, 'account:123');
    assert.equal(nextCalled, false);
  });

  it('handles POST /accounts (named async createAccount) successfully', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    let nextCalled = false;
    const result = await route.handler(
      {id: '456'},
      {send: val => val},
      () => { nextCalled = true; }
    );
    assert.equal(result, 'created:456');
    assert.equal(nextCalled, false);
  });

  it('handles GET /health synchronously', () => {
    const router = makeRouter();
    const route = router.routes[2];
    let nextCalled = false;
    const result = route.handler(
      {id: '0'},
      {send: val => val},
      () => { nextCalled = true; }
    );
    assert.equal(result, 'ok');
    assert.equal(nextCalled, false);
  });

  it('handles GET /orders/:id successfully', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    let nextCalled = false;
    const result = await route.handler(
      {id: 'ord-abc'},
      {send: val => val},
      () => { nextCalled = true; }
    );
    assert.equal(result, 'ORD-ABC');
    assert.equal(nextCalled, false);
  });

  it('handles DELETE /orders/:id successfully', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    let nextCalled = false;
    const result = await route.handler(
      {id: 'ord-xyz'},
      {send: val => val},
      () => { nextCalled = true; }
    );
    assert.equal(result, 'deleted:ord-xyz');
    assert.equal(nextCalled, false);
  });
});

describe('Error forwarding to next', () => {
  it('forwards rejection on GET /accounts/:id to next', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    let passedError = null;
    await route.handler(
      {id: '123', fail: true},
      {send: val => val},
      err => { passedError = err; }
    );
    assert.ok(passedError instanceof Error);
    assert.equal(passedError.message, 'account read');
  });

  it('forwards rejection on POST /accounts to next', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    let passedError = null;
    await route.handler(
      {id: '456', fail: true},
      {send: val => val},
      err => { passedError = err; }
    );
    assert.ok(passedError instanceof Error);
    assert.equal(passedError.message, 'account create');
  });

  it('forwards rejection on GET /orders/:id to next', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    let passedError = null;
    await route.handler(
      {id: 'ord-abc', fail: true},
      {send: val => val},
      err => { passedError = err; }
    );
    assert.ok(passedError instanceof Error);
    assert.equal(passedError.message, 'order read');
  });

  it('forwards rejection on DELETE /orders/:id to next', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    let passedError = null;
    await route.handler(
      {id: 'ord-xyz', fail: true},
      {send: val => val},
      err => { passedError = err; }
    );
    assert.ok(passedError instanceof Error);
    assert.equal(passedError.message, 'order delete');
  });
});

describe('Preserves unrelated exports and functions', () => {
  it('preserves documentation export', () => {
    assert.equal(documentation, "router.get('/fake', async handler)");
  });

  it('preserves unrelatedHelper without wrapping', async () => {
    await assert.rejects(async () => {
      await unrelatedHelper();
    }, /helper/);
  });

  it('preserves auditCallback without wrapping', async () => {
    await assert.rejects(async () => {
      await auditCallback();
    }, /audit/);
  });
});

